package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.text.*;import android.widget.*;import java.util.*;import java.util.concurrent.*;import org.json.*;

/** Parental launch gate inside Morph TV. Does not police other launchers. */
final class AppLocks {
 private static final ExecutorService crypto=Executors.newSingleThreadExecutor();
 private static final Map<Activity,Boolean> prompts=new WeakHashMap<>();
 private static SharedPreferences prefs(Context c){return c.getSharedPreferences("tvmorph-app-locks",0);}
 private static String t(Context c,String ar,String en){return FamilyText.t(c,ar,en);}
 private static Set<String> ids(Context c){return new HashSet<>(prefs(c).getStringSet("apps",Collections.emptySet()));}
 static boolean configured(Context c){return !prefs(c).getString("verifier","").isEmpty();}
 static boolean locked(Context c,String id){return configured(c)&&(ids(c).contains(id)||!prefs(c).getString("appPin:"+id,"").isEmpty());}
 private static EditText field(Activity a,String hint){EditText input=new EditText(a);input.setHint(hint);input.setSingleLine(true);input.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_DONE);input.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD);input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(8)});input.setSaveEnabled(false);return input;}
 static void guard(Activity a,String id,Runnable action){if(!ParentalTimer.allow(a,id))return;if(locked(a,id))verify(a,prefs(a).getString("appPin:"+id,"").isEmpty()?"verifier":"appPin:"+id,action);else action.run();}
 private static void verify(Activity a,Runnable done){verify(a,"verifier",done);}
 private static void verify(Activity a,String pinKey,Runnable done){
  if(a.isFinishing()||a.isDestroyed()||prompts.containsKey(a))return;prompts.put(a,true);
  EditText input=field(a,t(a,"الرقم السري · ٤ إلى ٨ أرقام","PIN · 4–8 digits"));
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle(t(a,"التطبيق مقفول","App locked")).setView(input).setPositiveButton(t(a,"فتح","Unlock"),null).setNegativeButton(t(a,"إلغاء","Cancel"),null).create();
  dialog.setOnDismissListener(d->{prompts.remove(a);hideKeyboard(a,input);});editorSubmit(input,dialog);dialog.setOnShowListener(d->{input.requestFocus();dialog.getButton(-1).setOnClickListener(v->{
   long wait=prefs(a).getLong("retryAt",0)-System.currentTimeMillis();if(wait>0){input.setError(t(a,"محاولات كثيرة. انتظر ","Too many attempts. Wait ")+((wait+999)/1000)+t(a," ثانية."," seconds."));return;}
   final String pin=input.getText().toString();input.setText("");if(!PinSecret.valid(pin)){input.setError(t(a,"استخدم ٤ إلى ٨ أرقام.","Use 4–8 digits."));return;}
   dialog.getButton(-1).setEnabled(false);final String verifier=prefs(a).getString(pinKey,"");
   crypto.execute(()->{boolean accepted=false;try{accepted=PinSecret.matches(pin,verifier);}catch(Exception ignored){}final boolean ok=accepted;a.runOnUiThread(()->{if(a.isDestroyed()||!dialog.isShowing())return;dialog.getButton(-1).setEnabled(true);if(ok&&verifier.equals(prefs(a).getString(pinKey,""))){prefs(a).edit().putInt("failures",0).putLong("retryAt",0).apply();dialog.dismiss();done.run();}else{int failures=prefs(a).getInt("failures",0)+1;prefs(a).edit().putInt("failures",failures>=5?0:failures).putLong("retryAt",failures>=5?System.currentTimeMillis()+30000:0).apply();input.setError(t(a,"الرقم غير صحيح.","Incorrect PIN."));}});});
  });});dialog.show();
 }
 private static void newPin(Activity a,Runnable done){newPin(a,"verifier",done);}
 private static void newPin(Activity a,String pinKey,Runnable done){
  LinearLayout panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(28,12,28,12);EditText first=field(a,t(a,"رقم جديد · ٤ إلى ٨ أرقام","New PIN · 4–8 digits")),second=field(a,t(a,"أعد كتابة الرقم","Confirm PIN"));panel.addView(first);panel.addView(second);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle(pinKey.equals("verifier")?t(a,"تعيين الرقم السري للأهل","Set app-lock PIN"):t(a,"تعيين رقم سري لهذا التطبيق","Set app PIN")).setView(panel).setPositiveButton(t(a,"حفظ","Save"),null).setNegativeButton(t(a,"إلغاء","Cancel"),null).create();
  dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String pin=first.getText().toString();if(!PinSecret.valid(pin)){first.setError(t(a,"استخدم ٤ إلى ٨ أرقام.","Use 4–8 digits."));return;}if(!pin.equals(second.getText().toString())){second.setError(t(a,"الرقمان مختلفان.","PINs do not match."));return;}first.setText("");second.setText("");dialog.getButton(-1).setEnabled(false);crypto.execute(()->{try{String hash=PinSecret.create(pin);a.runOnUiThread(()->{if(a.isDestroyed()||!dialog.isShowing())return;prefs(a).edit().putString(pinKey,hash).putInt("failures",0).putLong("retryAt",0).apply();dialog.dismiss();done.run();});}catch(Exception e){a.runOnUiThread(()->{if(dialog.isShowing()){dialog.getButton(-1).setEnabled(true);first.setError(t(a,"تعذّر حفظ الرقم. حاول مرة أخرى.","Could not save PIN. Try again."));}});}});}));dialog.setOnDismissListener(d->hideKeyboard(a,second));first.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_NEXT);editorSubmit(second,dialog);dialog.show();first.requestFocus();
 }
 private static void hideKeyboard(Activity a,android.view.View field){try{((android.view.inputmethod.InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(field.getWindowToken(),0);}catch(Exception ignored){}}
 private static void editorSubmit(EditText field,AlertDialog dialog){field.setOnEditorActionListener((v,action,event)->{if(action==android.view.inputmethod.EditorInfo.IME_ACTION_DONE||(event!=null&&event.getKeyCode()==android.view.KeyEvent.KEYCODE_ENTER&&event.getAction()==android.view.KeyEvent.ACTION_DOWN)){if(dialog.isShowing()&&dialog.getButton(-1).isEnabled())dialog.getButton(-1).performClick();return true;}return false;});}
 static void settings(TvActivity a){if(configured(a))verify(a,()->menu(a));else new AlertDialog.Builder(a).setTitle(t(a,"الرقابة الأبوية","Parental controls")).setMessage(t(a,"عيّن رقمًا سريًا للأهل لإدارة القفل والوقت لكل تطبيق على حدة. كل تطبيق يمكن أن يكون له رقمه الخاص. توقيت التطبيقات الخارجية يحتاج خدمة التنقل الاختيارية. الرقم لا يُحفظ كنص واضح ولا يُرسل للموبايل.","Set a parent PIN to manage individual app locks and time allowances. Each app can have its own PIN. External app timers need the optional navigation service. Your PIN is not stored as plain text or sent to the phone.")).setPositiveButton(t(a,"تعيين رقم سري","Set PIN"),(d,w)->newPin(a,()->menu(a))).setNegativeButton(t(a,"رجوع","Back"),null).show();}
 private static void menu(TvActivity a){new AlertDialog.Builder(a).setTitle(t(a,"الرقابة الأبوية","Parental controls")).setItems(new String[]{t(a,"اختيار التطبيقات المقفولة","Choose locked apps"),t(a,"وقت التطبيقات المسموح","App time allowances"),t(a,"تغيير الرقم السري للأهل","Change PIN"),t(a,"إلغاء الرقم والقفل","Remove PIN and locks")},(d,w)->{if(w==0)choose(a);else if(w==1)chooseTime(a);else if(w==2)newPin(a,()->menu(a));else new AlertDialog.Builder(a).setMessage(t(a,"إلغاء قفل كل التطبيقات؟","Remove all app locks?")).setPositiveButton(t(a,"إلغاء القفل","Remove locks"),(x,y)->{prefs(a).edit().clear().apply();ParentalTimer.clear(a);}).setNegativeButton(t(a,"رجوع","Back"),null).show();}).setNegativeButton(t(a,"رجوع","Back"),null).show();}
 private static void choose(TvActivity a){try{JSONArray apps=a.apps();String[] names=new String[apps.length()],keys=new String[apps.length()];boolean[] selected=new boolean[apps.length()];Set<String> locked=ids(a);for(int i=0;i<apps.length();i++){JSONObject app=apps.getJSONObject(i);keys[i]=app.getString("id");names[i]=app.getString("name");selected[i]=locked.contains(keys[i]);}new AlertDialog.Builder(a).setTitle(t(a,"اختيار التطبيقات المقفولة","Choose locked apps")).setMultiChoiceItems(names,selected,(d,i,on)->selected[i]=on).setPositiveButton(t(a,"حفظ","Save"),(d,w)->{Set<String> result=new HashSet<>();for(int i=0;i<keys.length;i++)if(selected[i])result.add(keys[i]);SharedPreferences.Editor edit=prefs(a).edit().putStringSet("apps",result);for(String id:keys)if(!result.contains(id))edit.remove("appPin:"+id);edit.apply();}).setNegativeButton(t(a,"إلغاء","Cancel"),null).show();}catch(Exception e){android.widget.Toast.makeText(a,t(a,"تعذّر قراءة التطبيقات.","Could not read TV apps."),1).show();}}
 static void parent(Activity a,Runnable done){if(configured(a))verify(a,done);else newPin(a,done);}
 static void appPin(TvActivity a,String id){if(!valid(a,id))return;parent(a,()->newPin(a,"appPin:"+id,()->{Set<String> all=ids(a);all.add(id);prefs(a).edit().putStringSet("apps",all).apply();}));}
 static void unlockApp(TvActivity a,String id){if(!valid(a,id))return;parent(a,()->{Set<String> all=ids(a);all.remove(id);prefs(a).edit().putStringSet("apps",all).remove("appPin:"+id).apply();});}
 static boolean valid(TvActivity a,String id){try{JSONArray apps=a.apps();for(int i=0;i<apps.length();i++)if(id.equals(apps.getJSONObject(i).getString("id")))return true;}catch(Exception ignored){}return false;}
 static void timerSettings(Activity a,String id){parent(a,()->ParentalTimer.configure(a,id));}
 private static void chooseTime(TvActivity a){try{JSONArray apps=a.apps();String[] names=new String[apps.length()],keys=new String[apps.length()];for(int i=0;i<apps.length();i++){JSONObject app=apps.getJSONObject(i);keys[i]=app.getString("id");long left=ParentalTimer.remaining(a,keys[i]);names[i]=app.getString("name")+" · "+(left<0?t(a,"بدون حد زمني","No time limit"):t(a,"الدقائق المتبقية: ","Remaining minutes: ")+(left+59999)/60000);}new AlertDialog.Builder(a).setTitle(t(a,"وقت التطبيقات المسموح","App time allowances")).setItems(names,(d,w)->ParentalTimer.configure(a,keys[w])).setNegativeButton(t(a,"رجوع","Back"),null).show();}catch(Exception ignored){}}

}
